llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "Labetalol, the closest structural analogue sharing the beta-hydroxy secondary amine and phenethylamine motif, had a mean systemic bioavailability of 26 ± 3% after oral dosing in healthy volunteers, which is above the 20% threshold despite extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Sotalol, a beta-blocker with a similar ionizable secondary amine and beta-hydroxy aryl core, has an absolute oral bioavailability of 90-100% in humans, indicating that this class of polar, basic molecules can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Metoprolol, another basic beta-blocker with significant first-pass metabolism, has an absolute oral bioavailability of 38-60% in humans, supporting F >=20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Bevantolol, which contains a phenethylamine secondary amine linked to a beta-hydroxy aryl ether, showed a mean absolute oral bioavailability of 57% (range 26-98%) in healthy volunteers, supporting high bioavailability for the query's flexible basic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Phenylpropanolamine, sharing the beta-hydroxy phenethylamine core, had an absolute oral bioavailability of 61.9 ± 5.9% in healthy volunteers, demonstrating that the query's central amino alcohol does not inherently limit oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vorinostat, despite a polar hydroxamic acid and anilide structure, has an absolute oral bioavailability of approximately 43% in humans, indicating that high polar surface area alone does not push F below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues, including the closest structural match labetalol (F 26%), sotalol (90-100%), metoprolol (38-60%), bevantolol (57%), phenylpropanolamine (62%), and vorinostat (43%), support F >=20%. The query's higher polarity and ionization introduce uncertainty, but no affirmative evidence indicates F <20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The closest analogue labetalol has F near the 20% threshold; small changes in first-pass metabolism could cross below threshold.",
    "First-pass metabolism and transporter/efflux behavior of the query are unknown.",
    "Low neutral fraction at pH 7.4 may reduce permeability, but beta-blocker analogues with similar ionization still achieve F >=20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

